import { test, expect } from '@playwright/test';

test.describe('Image Alt Text Accessibility', () => {
  let page;

  test.beforeEach(async ({ browser }) => {
    page = await browser.newPage();
    await page.goto('about:blank');
  });

  test('should verify all images have descriptive alt text', async () => {
    // Create a test page with images
    await page.setContent(`
      <html>
        <body>
          <img src="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNk+M9QDwADhgGAWjR9awAAAABJRU5ErkJggg==" alt="Company logo" />
          <img src="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNk+M9QDwADhgGAWjR9awAAAABJRU5ErkJggg==" alt="Product screenshot showing dashboard" />
          <img src="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNk+M9QDwADhgGAWjR9awAAAABJRU5ErkJggg==" alt="" role="presentation" />
        </body>
      </html>
    `);

    // Get all images on the page
    const images = await page.locator('img').all();

    // Verify we have images
    expect(images.length).toBeGreaterThan(0);

    // Check each image for alt text
    for (const image of images) {
      const altText = await image.getAttribute('alt');
      const role = await image.getAttribute('role');

      // Images should either have descriptive alt text or be marked as presentation
      if (role === 'presentation') {
        expect(altText).toBe('');
      } else {
        expect(altText).toBeTruthy();
        expect(altText?.length).toBeGreaterThan(0);
      }
    }
  });

